"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["23370"],{79093(e){e.exports=JSON.parse('{"id":"FIN-370","slug":"nonperforming-loan","term":"Nonperforming Loan (NPL)","also_known_as":["NPL"],"difficulty":"Intermediate","definition":"A nonperforming loan (NPL) is a loan on which the borrower has stopped making scheduled payments for a set period, usually 90 days or more, or is unlikely to repay in full.","explanation":["When a borrower falls far behind on payments, the loan is classed as nonperforming. Banks no longer expect to collect interest and principal as agreed, and may not recover the full amount.","For example, if a business borrower has not paid interest or principal on its loan for four months, the bank would normally classify the loan as nonperforming.","Banks track the NPL ratio, which divides nonperforming loans by total loans. If a bank has 50 million of NPLs out of 1,000 million of total loans, its NPL ratio is 5%. A rising ratio signals growing credit problems.","Nonperforming loans reduce a bank\'s income, because interest is not being received, and require banks to set aside money to cover expected losses through loan loss provisions. High levels of NPLs can weaken a bank\'s capital, limit its ability to lend and, if widespread across a banking system, slow the whole economy. Banks deal with NPLs by restructuring loans, seizing and selling collateral, selling the loans to specialist investors or writing them off."],"note":"","total":1500,"prev":{"slug":"noncontrolling-interest","term":"Noncontrolling Interest"},"next":{"slug":"nonrefundable-tax-credit","term":"Nonrefundable Tax Credit"}}')}}]);